from admissions_records import *
def s(u,en,ru):return S(u,L(en,ru),access='web-html-read')
def i(n,sec=None):
 d={'accepted':True,'min':n,'role':'admission'}
 if sec is not None:d['sections']={x:sec for x in ['reading','writing','listening','speaking']}
 return d
def t(old=None,new=None):return {'accepted':True,'scales':([{'period':'pre2026','min':old}] if old else [])+([{'period':'post2026','min':new}] if new else [])}
record('towson-university',[route(english={'requirement':'required-unless-exempt','ielts':i(6,5.5),'toefl':t(70,4),'alternatives':L('TOEFL legacy sections 17; new sections 3.5. PTE 49, DET 105, iTEP 3.9, TOEFL Essentials 8 each 8; SAT EBRW 540 or ACT English 21 are language alternatives.','Прежние секции TOEFL 17; новые 3,5. PTE 49, DET 105, iTEP 3,9, TOEFL Essentials 8 с каждой 8; SAT EBRW 540 либо ACT English 21 — языковые альтернативы.'),'waiver':L('At least three years of education in a listed country; starred countries additionally require an English-language school system. This is not a universal school-MOI waiver.','Не менее трёх лет образования в стране списка; для стран со звёздочкой дополнительно требуется англоязычная школьная система. Это не универсальное освобождение по MOI.')},academic={'satPolicy':'unknown'},sources=[s('https://www.towson.edu/admissions/international/english-proficiency.html','Towson undergraduate English table and exemptions','Towson: бакалаврская языковая таблица и освобождения')])],'Used undergraduate 6.0/5.5 rather than graduate 6.5/6.0 and separated academic from language subscores.', ['Fall 2027 cycle, IELTS test variant and independent SAT/ACT selection policy remain unconfirmed.'])

esf='https://www.esf.edu/admissions/apply/international-students/'
en={'requirement':'required-unless-exempt','ielts':i(6),'toefl':t(79,4),'alternatives':L('Undergraduate IELTS Writing 5; DET 100. SAT EBRW 500 or ACT composite 22 are English alternatives; Syracuse ELI level 4 and specified non-ESL college English also qualify. TOEFL MyBest accepted.','Бакалаврский IELTS Writing 5; DET 100. SAT EBRW 500 либо ACT composite 22 — альтернативы английского; также Syracuse ELI 4 и указанный не-ESL английский колледжа. TOEFL MyBest принимается.'),'waiver':L('US high-school graduates, US GED or high-school equivalency holders may be waived; not a universal nationality exemption.','Возможно освобождение выпускников школы США, обладателей US GED или школьного эквивалента; не универсальное освобождение по гражданству.')}
en['ielts']['sections']={'writing':5}
record('suny-esf',[route(english=en,academic={'satPolicy':'optional','note':L('ESF first-year page explicitly permits choosing whether SAT/ACT are considered for bachelor admission. English proof remains independent.','Страница первокурсника ESF прямо разрешает выбирать учёт SAT/ACT при бакалаврском приёме. Языковое подтверждение сохраняется отдельно.')},documents=[L('First-year foreign school credentials need an approved international evaluation and complete English translations; applicant self-translations not accepted.','Иностранные школьные документы первокурсника требуют одобренной международной оценки и полного английского перевода; самостоятельный перевод не принимается.')],sources=[s(esf,'ESF undergraduate language and credentials','ESF: бакалаврский язык и документы'),s('https://www.esf.edu/admissions/apply/first-year/index.php','ESF first-year optional academic tests','ESF: необязательные академические тесты первокурсников')])],'Separated undergraduate/graduate columns and preserved IELTS Writing 5 independently from overall 6.', ['Fall 2027-labelled rules, IELTS test variant and new TOEFL section minima remain unconfirmed.'])

np='https://www.newpaltz.edu/admissions/international/undergraduate.html'
aa={'satPolicy':'conditional','note':L('SUNY temporarily allows optional SAT/ACT, with exceptions for selected programmes, some merit awards and NCAA eligibility. English proof is a separate obligation. Exact New Paltz exceptions for 2027 require confirmation.','SUNY временно разрешает необязательные SAT/ACT, с исключениями для некоторых программ, merit awards и NCAA. Английский — отдельное требование. Точные исключения New Paltz на 2027 требуют подтверждения.')}
sources=[s(np,'New Paltz international undergraduate direct and HELP routes','New Paltz: прямой международный бакалавриат и HELP'),s('https://www.system.suny.edu/attend/apply-to-suny/testing-requirements/','SUNY temporary academic testing policy and exceptions','SUNY: временная политика академических тестов и исключения')]
record('suny-new-paltz',[route(id='direct',english={'requirement':'required-unless-exempt','ielts':i(6.5,6),'toefl':t(80,4),'alternatives':L('New TOEFL sections at least 3.5; PTE Academic 58, SAT Reading/Writing 550 or qualifying English Composition I and II with C+ or better.','Новые секции TOEFL не менее 3,5; PTE Academic 58, SAT Reading/Writing 550 либо подходящие English Composition I и II с C+ и выше.')},academic=aa,sources=sources),route(id='help-pathway',kind='degree-with-conditions',label=L('Haggerty English Language Pathway — conditional entry','Haggerty English Language Pathway — условный приём'),english={'requirement':'programme-dependent','ielts':{'accepted':None},'note':L('Conditional admission may be offered without English proof after other academic requirements are met. Placement after arrival; full-time degree study requires HELP completion or the required test result. This is not confirmed unconditional direct admission.','Возможен условный приём без языкового подтверждения при выполнении остальных академических требований. Распределение по приезде; полноценное обучение степени требует HELP либо нужного теста. Это не подтверждённый безусловный прямой приём.')},academic=aa,sources=sources)],'Separated direct 6.5/6 entry from the conditional HELP route and preserved new TOEFL section minima.', ['Fall 2027 cycle, exact degree-specific academic exceptions and IELTS variant remain unconfirmed.'])

record('appalachian-state-university',[route(english={'requirement':'required-unless-exempt','ielts':i(6),'toefl':{'accepted':True,'scales':[{'period':'legacy','min':78,'recommended':85,'sections':{x:16 for x in ['reading','writing','listening','speaking']}}]},'alternatives':L('DET 100; SAT EBRW 500 or ACT composite 20 are English alternatives. TOEFL 85 is preferred, while 78 with sections 16 is the published minimum.','DET 100; SAT EBRW 500 либо ACT composite 20 — альтернативы английского. TOEFL 85 предпочтителен, тогда как 78 с секциями 16 — опубликованный минимум.'),'waiver':L('The page names country/school-language and specific four-year school-history routes. These require assessment of the actual school record, not citizenship alone.','Страница называет условия страны/языка школы и отдельный маршрут четырёх школьных лет. Нужна оценка фактических школьных документов, а не только гражданства.')},academic={'satPolicy':'conditional','note':L('First-year applicants below weighted GPA 2.8 on the university-converted 4.0 scale must submit SAT/ACT. This is separate from language-test substitution.','Первокурсники с weighted GPA ниже 2,8 по пересчитанной университетом шкале 4,0 должны подать SAT/ACT. Это отдельно от замены языкового теста.')},sources=[s('https://admissions.appstate.edu/apply/international-student','App State international first-year testing and language','App State: тесты и язык международного первокурсника')])],'Separated language minimum/recommendation and GPA-dependent academic testing.', ['Fall 2027-specific policy, IELTS sections/version, new TOEFL scale and individual waiver eligibility remain unconfirmed.'])

mt='https://intered.mtsu.edu/admission/'
ma={'satPolicy':'conditional','note':L('Guaranteed admission has alternatives: GPA 3.0, ACT 22 or SAT 1100; another route pairs GPA 2.7 with ACT 19/SAT 990. Admission by review is separate. No blanket SAT requirement or guaranteed eligibility follows from language scores.','Гарантированный приём имеет альтернативы: GPA 3,0, ACT 22 либо SAT 1100; другой маршрут сочетает GPA 2,7 с ACT 19/SAT 990. Приём через review отдельный. Из языка не следует всеобщая обязательность SAT или гарантированный допуск.')}
ms=[s(mt,'MTSU international undergraduate language and academic alternatives','MTSU: международные бакалаврские языковые и академические альтернативы')]
record('middle-tennessee-state-university',[route(id='general',english={'requirement':'required-unless-exempt','ielts':i(5.5),'toefl':t(new=4),'alternatives':L('General programmes: DET 85, iTEP 3.5, PTE 59 or ELS 110. Professional Pilot and Nursing have higher language requirements.','Общие программы: DET 85, iTEP 3,5, PTE 59 либо ELS 110. Для Professional Pilot и Nursing языковые требования выше.'),'waiver':L('Specified citizenship, school/college English and SAT Verbal 510/ACT composite 22 alternatives; school-medium cases are individually qualified, not automatic for every school.','Указанные гражданство, английский школы/колледжа и SAT Verbal 510/ACT composite 22; школьные случаи имеют ограничения, не автоматичны для любой школы.')},academic=ma,sources=ms),route(id='pilot-nursing',label=L('Professional Pilot / Nursing — higher language category','Professional Pilot / Nursing — повышенная языковая категория'),english={'requirement':'required-unless-exempt','ielts':i(6),'toefl':t(new=4.5),'alternatives':L('DET 95, iTEP 3.8, PTE 70 or ELS 112; separate programme selection requirements may apply.','DET 95, iTEP 3,8, PTE 70 либо ELS 112; возможны отдельные условия отбора программы.')},academic=ma,sources=ms)],'Kept IELTS 5.5 general and 6.0 Pilot/Nursing distinct; no universal SAT rule from one guaranteed-admission pathway.', ['Fall 2027-labelled confirmation, IELTS variant/sections and exact programme selection requirements remain unconfirmed.'])

record('grand-valley-state-university',[route(english={'requirement':'required-unless-exempt','ielts':i(6.5),'toefl':t(86,4.5),'alternatives':L('DET 105, PTE 53, Cambridge C1/C2 180, MET 52; SAT EBRW 470 or ACT English 15 are English alternatives. TOEFL Home accepted; MyBest/Essentials not accepted.','DET 105, PTE 53, Cambridge C1/C2 180, MET 52; SAT EBRW 470 либо ACT English 15 — языковые альтернативы. TOEFL Home принимается; MyBest/Essentials — нет.')},academic={'satPolicy':'unknown'},sources=[s('https://www.gvsu.edu/admissions/international-application-14','GVSU undergraduate application language section','GVSU: бакалаврский языковой раздел заявления')])],'Used the undergraduate language section; SAT/ACT English alternatives are not academic selection requirements.', ['Fall 2027 confirmation, IELTS variant/sections, undergraduate waiver details and independent SAT/ACT policy remain unconfirmed.'])

record('elmhurst-university',[route(english={'requirement':'required-unless-exempt','ielts':i(6.5),'toefl':t(79,4),'alternatives':L('DET 110; ACT English AND Reading 22, SAT EBRW 520; Cambridge 160; PTE Academic/Express 55 explicitly for 2027 onward. British/IB/US-international-school options have their own English conditions.','DET 110; ACT English И Reading 22, SAT EBRW 520; Cambridge 160; PTE Academic/Express 55 прямо для 2027 и далее. Британские/IB/американские международные школьные варианты имеют собственные условия английского.'),'waiver':L('The country option requires both citizenship and high-school attendance in a listed country, not citizenship alone.','Страновой вариант требует одновременно гражданства и обучения в школе страны списка, а не одного гражданства.')},academic={'satPolicy':'unknown'},sources=[s('https://www.elmhurst.edu/admission/international-students/admission-requirements/first-year/','Elmhurst international first-year English alternatives','Elmhurst: языковые альтернативы международного первокурсника')])],'Separated ACT section requirements and qualified school-history alternatives from an academic-test obligation.', ['Fall 2027-labelled general policy, IELTS variant/sections and independent SAT/ACT selection rule remain unconfirmed.'])
